    let sorted = sort(&lower);
    inputs
        .iter()
        .filter(|input| {
            let input_lower = input.to_lowercase();
            lower != input_lower && sorted == sort(&input_lower)
        })
        .cloned()
        .collect()
}

export const isMysteryNumber = (input) => {
  const bigInput = BigInt(input);

  const digits = [...String(bigInput)];

  const sum = digits.reduce(
    (total, current) => total + BigInt(current) ** BigInt(digits.length),
    BigInt(0),
  );

  return sum === bigInput;
};

